-- Palomnik presentation only; preserve original content, photos, coordinates and accounts.

INSERT OR IGNORE INTO settings(key,value) SELECT 'palomnik_unified','1' WHERE EXISTS(SELECT 1 FROM settings_i18n WHERE key='site_title' AND lang='ru' AND value='Паломник по Грузии') AND (SELECT COUNT(DISTINCT slug) FROM elements WHERE slug IN ('apostol-andrey','svyataya-nina','sirijskie-otcy'))=3;

INSERT INTO element_i18n(element_id,lang,eyebrow,title,body) SELECT r.element_id,'en','Three waves of preaching','How Georgia became Christian','Three waves of preaching over six centuries: the Apostle Andrew, Saint Nino, Equal to the Apostles, and the Thirteen Assyrian Fathers. This site follows in their footsteps.' FROM element_i18n r WHERE r.lang='ru' AND r.eyebrow IS 'Три волны проповеди' AND r.title IS 'Как Грузия стала христианской' AND r.body IS 'Три волны проповеди за шесть веков: апостол Андрей, равноапостольная Нина и тринадцать сирийских отцов. Этот сайт проведёт по их следам.' AND EXISTS (SELECT 1 FROM settings WHERE key='palomnik_unified' AND value='1') ON CONFLICT(element_id,lang) DO UPDATE SET eyebrow=CASE WHEN COALESCE(element_i18n.eyebrow,'')='' THEN excluded.eyebrow ELSE element_i18n.eyebrow END,title=CASE WHEN COALESCE(element_i18n.title,'')='' THEN excluded.title ELSE element_i18n.title END,body=CASE WHEN COALESCE(element_i18n.body,'')='' THEN excluded.body ELSE element_i18n.body END;

INSERT INTO element_i18n(element_id,lang,title,subtitle,body,seo_title,seo_description) SELECT r.element_id,'en','The Apostle Andrew and his companions','1st century. The first preaching in the land entrusted to the Mother of God','Georgia is the first land entrusted to the Mother of God. According to tradition, the Mother of God herself sent the Apostle Andrew the First-Called here and gave him her image Not Made by Hands.

Together with his companions, the Apostles Simon the Zealot and Matthias, he came from the shores of the Black Sea, crossed the mountains of Adjara into Samtskhe and laid the foundations of Christianity in Georgia, three centuries before Saint Nino.','The Apostle Andrew and his companions — Pilgrim in Georgia','Georgia is the first land entrusted to the Mother of God. According to tradition, the Mother of God herself sent the Apostle Andrew the First-Called here and gave him her image Not Made by Hands.' FROM element_i18n r WHERE r.lang='ru' AND r.title IS 'Апостол Андрей и его спутники' AND r.subtitle IS 'I век. Первая проповедь в Удел Богородицы' AND r.body IS 'Грузия — первый удел Богородицы. По преданию, Сама Богородица послала сюда апостола Андрея Первозванного и вручила ему Свой Нерукотворный образ.

Вместе со спутниками, апостолами Симоном Кананитом и Матфием, он пришёл с берегов Чёрного моря, прошёл через горы Аджарии в Самцхе и положил начало христианству в Грузии — за три века до святой Нины.' AND r.seo_title IS 'Апостол Андрей и его спутники — Паломник' AND r.seo_description IS 'Грузия — первый удел Богородицы. По преданию, Сама Богородица послала сюда апостола Андрея Первозванного и вручила ему Свой Нерукотворный образ.' AND EXISTS (SELECT 1 FROM settings WHERE key='palomnik_unified' AND value='1') ON CONFLICT(element_id,lang) DO UPDATE SET title=CASE WHEN COALESCE(element_i18n.title,'')='' THEN excluded.title ELSE element_i18n.title END,subtitle=CASE WHEN COALESCE(element_i18n.subtitle,'')='' THEN excluded.subtitle ELSE element_i18n.subtitle END,body=CASE WHEN COALESCE(element_i18n.body,'')='' THEN excluded.body ELSE element_i18n.body END,seo_title=CASE WHEN COALESCE(element_i18n.seo_title,'')='' THEN excluded.seo_title ELSE element_i18n.seo_title END,seo_description=CASE WHEN COALESCE(element_i18n.seo_description,'')='' THEN excluded.seo_description ELSE element_i18n.seo_description END;

INSERT INTO element_i18n(element_id,lang,title) SELECT r.element_id,'en','The Apostles' FROM element_i18n r WHERE r.lang='ru' AND r.title IS 'Апостолы' AND EXISTS (SELECT 1 FROM settings WHERE key='palomnik_unified' AND value='1') ON CONFLICT(element_id,lang) DO UPDATE SET title=CASE WHEN COALESCE(element_i18n.title,'')='' THEN excluded.title ELSE element_i18n.title END;

INSERT INTO element_i18n(element_id,lang,title,subtitle,body,seo_title,seo_description) SELECT r.element_id,'en','The Apostle Andrew the First-Called','The First-Called Apostle and preacher in Georgia','Georgia is the first land entrusted to the Mother of God. According to tradition, the Mother of God herself sent the Apostle Andrew the First-Called here and gave him her image Not Made by Hands.

Together with his companions, the Apostles Simon the Zealot and Matthias, he came from the shores of the Black Sea, crossed the mountains of Adjara into Samtskhe and laid the foundations of Christianity in Georgia, three centuries before Saint Nino.','The Apostle Andrew the First-Called — Pilgrim in Georgia','Georgia is the first land entrusted to the Mother of God. According to tradition, the Mother of God herself sent the Apostle Andrew the First-Called here and gave him her image Not Made by Hands.' FROM element_i18n r WHERE r.lang='ru' AND r.title IS 'Апостол Андрей Первозванный' AND r.subtitle IS 'Первозванный апостол и проповедник в Грузии' AND r.body IS 'Грузия — первый удел Богородицы. По преданию, Сама Богородица послала сюда апостола Андрея Первозванного и вручила ему Свой Нерукотворный образ.

Вместе со спутниками, апостолами Симоном Кананитом и Матфием, он пришёл с берегов Чёрного моря, прошёл через горы Аджарии в Самцхе и положил начало христианству в Грузии — за три века до святой Нины.' AND r.seo_title IS 'Апостол Андрей Первозванный — Паломник' AND r.seo_description IS 'Грузия — первый удел Богородицы. По преданию, Сама Богородица послала сюда апостола Андрея Первозванного и вручила ему Свой Нерукотворный образ.' AND EXISTS (SELECT 1 FROM settings WHERE key='palomnik_unified' AND value='1') ON CONFLICT(element_id,lang) DO UPDATE SET title=CASE WHEN COALESCE(element_i18n.title,'')='' THEN excluded.title ELSE element_i18n.title END,subtitle=CASE WHEN COALESCE(element_i18n.subtitle,'')='' THEN excluded.subtitle ELSE element_i18n.subtitle END,body=CASE WHEN COALESCE(element_i18n.body,'')='' THEN excluded.body ELSE element_i18n.body END,seo_title=CASE WHEN COALESCE(element_i18n.seo_title,'')='' THEN excluded.seo_title ELSE element_i18n.seo_title END,seo_description=CASE WHEN COALESCE(element_i18n.seo_description,'')='' THEN excluded.seo_description ELSE element_i18n.seo_description END;

INSERT INTO element_i18n(element_id,lang,title,subtitle,body,seo_title,seo_description) SELECT r.element_id,'en','The Apostle Simon the Zealot','One of the Twelve Apostles','The Apostle Simon the Zealot was one of the Twelve. Together with Andrew, he reached Abasgia on the Black Sea coast and remained there to preach when Andrew travelled north. According to tradition, Simon prayed in a cave above a river and suffered martyrdom around AD 55. A church was built over his burial place in the 9th–10th centuries, and in the late 19th century Russian monks founded the New Athos Monastery in his name. His feast day is 23 May (10 May, Old Style).','The Apostle Simon the Zealot — Pilgrim in Georgia','The Apostle Simon the Zealot was one of the Twelve. Together with Andrew, he reached Abasgia on the Black Sea coast and remained there to preach when Andrew tra' FROM element_i18n r WHERE r.lang='ru' AND r.title IS 'Апостол Симон Кананит' AND r.subtitle IS 'Один из Двенадцати апостолов' AND r.body IS 'Апостол Симон Кананит — один из Двенадцати. Вместе с Андреем он дошёл до Абазгии на Черноморском побережье и остался там проповедовать, когда Андрей ушёл на север. По преданию, Симон молился в пещере над рекой, а около 55 года принял мученическую кончину. Над местом его погребения в IX–X веках поставили храм, а в конце XIX века русские монахи основали Ново-Афонский монастырь его имени. Память — 23 мая (10 мая по старому стилю).' AND r.seo_title IS 'Апостол Симон Кананит — Паломник' AND r.seo_description IS 'Апостол Симон Кананит — один из Двенадцати. Вместе с Андреем он дошёл до Абазгии на Черноморском побережье и остался там проповедовать, когда Андрей ушёл на сев' AND EXISTS (SELECT 1 FROM settings WHERE key='palomnik_unified' AND value='1') ON CONFLICT(element_id,lang) DO UPDATE SET title=CASE WHEN COALESCE(element_i18n.title,'')='' THEN excluded.title ELSE element_i18n.title END,subtitle=CASE WHEN COALESCE(element_i18n.subtitle,'')='' THEN excluded.subtitle ELSE element_i18n.subtitle END,body=CASE WHEN COALESCE(element_i18n.body,'')='' THEN excluded.body ELSE element_i18n.body END,seo_title=CASE WHEN COALESCE(element_i18n.seo_title,'')='' THEN excluded.seo_title ELSE element_i18n.seo_title END,seo_description=CASE WHEN COALESCE(element_i18n.seo_description,'')='' THEN excluded.seo_description ELSE element_i18n.seo_description END;

INSERT INTO element_i18n(element_id,lang,title,subtitle,body,seo_title,seo_description) SELECT r.element_id,'en','The Apostle Matthias','The Apostle chosen to replace Judas','The Apostle Matthias was chosen by lot to replace Judas, restoring the number of the Apostles to twelve. According to Georgian tradition, he preached in southwestern Georgia and was buried in the ancient fortress of Gonio near Batumi. A symbolic tomb is shown there today, on the site of the Roman praetorium. His feast day is 22 August (9 August, Old Style).','The Apostle Matthias — Pilgrim in Georgia','The Apostle Matthias was chosen by lot to replace Judas, restoring the number of the Apostles to twelve. According to Georgian tradition, he preached in southwe' FROM element_i18n r WHERE r.lang='ru' AND r.title IS 'Апостол Матфий' AND r.subtitle IS 'Апостол, избранный вместо Иуды' AND r.body IS 'Апостол Матфий был избран по жребию вместо Иуды, чтобы снова стало двенадцать апостолов. По грузинскому преданию, он проповедовал на юго-западе Грузии и похоронен в древней крепости Гонио у Батуми. Там, на месте римской претории, сегодня показывают его символическую гробницу. Память — 22 августа (9 августа по старому стилю).' AND r.seo_title IS 'Апостол Матфий — Паломник' AND r.seo_description IS 'Апостол Матфий был избран по жребию вместо Иуды, чтобы снова стало двенадцать апостолов. По грузинскому преданию, он проповедовал на юго-западе Грузии и похорон' AND EXISTS (SELECT 1 FROM settings WHERE key='palomnik_unified' AND value='1') ON CONFLICT(element_id,lang) DO UPDATE SET title=CASE WHEN COALESCE(element_i18n.title,'')='' THEN excluded.title ELSE element_i18n.title END,subtitle=CASE WHEN COALESCE(element_i18n.subtitle,'')='' THEN excluded.subtitle ELSE element_i18n.subtitle END,body=CASE WHEN COALESCE(element_i18n.body,'')='' THEN excluded.body ELSE element_i18n.body END,seo_title=CASE WHEN COALESCE(element_i18n.seo_title,'')='' THEN excluded.seo_title ELSE element_i18n.seo_title END,seo_description=CASE WHEN COALESCE(element_i18n.seo_description,'')='' THEN excluded.seo_description ELSE element_i18n.seo_description END;

INSERT INTO element_i18n(element_id,lang,title,subtitle,body,seo_title,seo_description) SELECT r.element_id,'en','The land entrusted to the Mother of God','Why the Apostle came to Georgia','After the Ascension of the Lord, the Apostles cast lots to decide which country each would go to and preach. According to Georgian tradition, Iberia, the ancient name for Georgia, fell to the Mother of God.

But in a vision the Lord revealed that she should remain in Jerusalem and send the Apostle Andrew the First-Called to the land entrusted to her. The Mother of God then pressed a wooden panel to her face, and her image with the Child was imprinted upon it. She gave this image Not Made by Hands to the Apostle as a blessing for his journey.

Georgia is still called the land entrusted to the Mother of God. The Georgian Church celebrates this dedication on 12 May, the same day it commemorates the Apostle Andrew’s arrival in Georgia. The Apostle’s general feast day is 13 December (30 November, Old Style).

The tradition has come down to us in the Georgian chronicle Kartlis Tskhovreba (11th century). Greek accounts of the Apostle’s life are older, but it is the Georgian tradition that connects his arrival with the lot of the Mother of God.','The land entrusted to the Mother of God — Pilgrim in Georgia','Why the Apostle came to Georgia' FROM element_i18n r WHERE r.lang='ru' AND r.title IS 'Удел Богородицы' AND r.subtitle IS 'Почему апостол пришёл именно в Грузию' AND r.body IS 'После Вознесения Господня апостолы бросили жребий: кому в какую страну идти с проповедью. По грузинскому преданию, Богородице выпала Иверия — так в древности называли Грузию.

Но Господь в видении открыл Ей, что Она должна остаться в Иерусалиме, а в Свой удел послать апостола Андрея Первозванного. Тогда Богородица приложила к Своему лику доску — и на ней запечатлелся Её образ с Младенцем. Этот Нерукотворный образ Она вручила апостолу как благословение в путь.

Поэтому Грузию и сегодня называют уделом Богородицы. Праздник Удела Богоматери Грузинская Церковь совершает 12 мая — в один день с памятью о приходе апостола Андрея в Грузию. Общецерковная память апостола — 13 декабря (30 ноября по старому стилю).

Предание дошло до нас в грузинской летописи «Картлис цховреба» (XI век). Греческие жития апостола древнее, но именно грузинская традиция связывает его приход со жребием Богородицы.' AND r.seo_title IS 'Удел Богородицы — Паломник по Грузии' AND r.seo_description IS 'Почему апостол пришёл именно в Грузию' AND EXISTS (SELECT 1 FROM settings WHERE key='palomnik_unified' AND value='1') ON CONFLICT(element_id,lang) DO UPDATE SET title=CASE WHEN COALESCE(element_i18n.title,'')='' THEN excluded.title ELSE element_i18n.title END,subtitle=CASE WHEN COALESCE(element_i18n.subtitle,'')='' THEN excluded.subtitle ELSE element_i18n.subtitle END,body=CASE WHEN COALESCE(element_i18n.body,'')='' THEN excluded.body ELSE element_i18n.body END,seo_title=CASE WHEN COALESCE(element_i18n.seo_title,'')='' THEN excluded.seo_title ELSE element_i18n.seo_title END,seo_description=CASE WHEN COALESCE(element_i18n.seo_description,'')='' THEN excluded.seo_description ELSE element_i18n.seo_description END;

INSERT INTO element_i18n(element_id,lang,title,subtitle,body,seo_title,seo_description) SELECT r.element_id,'en','The journey through Georgia','From the sea across the mountains, step by step','According to the Georgian chronicle, the Apostle Andrew travelled through Georgia along this route:

1. Trebizond. His first stop on the Black Sea coast, where he baptised the Mingrelians (Laz) living there.

2. Adjara. The Apostle performed miracles and, with the help of the icon, brought a healing spring out of the earth and baptised people in it. He founded a church of the Mother of God and left a copy of the image Not Made by Hands there. Local tradition connects the site with the village of Didachara in mountainous Adjara.

3. The Iron Cross. Crossing the mountains between Adjara and Samtskhe, the Apostle erected an iron cross on a summit. The mountain was thereafter called Rkinis Jvari, “Iron Cross”.

4. The Odzrkhe Gorge. The Apostle entered Samtskhe through this gorge. Today the resort of Abastumani stands here.

5. Mount Zaden. The inhabitants offered sacrifices to idols here; the Apostle destroyed them and continued on his way.

6. Atskuri. The great miracle of the journey was the raising of the ruler’s son and the baptism of the whole region (see the Atskuri card).

7. Further across Georgia. The Apostle preached in Tao and Klarjeti, Mingrelia, Svaneti and Abasgia.

8. Northwards. He then travelled to the Alans and Zichians, and from there to Scythia.

For some places the exact location is known; for others only a name from the chronicle survives. We indicate this distinction on the map.','The journey through Georgia — Pilgrim in Georgia','From the sea across the mountains, step by step' FROM element_i18n r WHERE r.lang='ru' AND r.title IS 'Путь по Грузии' AND r.subtitle IS 'От моря через горы — шаг за шагом' AND r.body IS 'По грузинской летописи, апостол Андрей прошёл по Грузии так:

1. Трапезунд. Первая остановка на берегу Чёрного моря: апостол крестил живших здесь мегрелов (лазов).

2. Аджария. Апостол творил чудеса, с помощью иконы извёл из земли целебный источник и крестил в нём людей. Здесь он заложил храм Богородицы и оставил в нём копию Нерукотворного образа. Местная традиция связывает это место с селом Дидачара в горной Аджарии.

3. Железный крест. Переходя горы между Аджарией и Самцхе, апостол водрузил на вершине железный крест. С тех пор гору называли Ркинис-Джвари — «Железный крест».

4. Ущелье Одзрхе. Через него апостол вошёл в Самцхе. Сегодня на этом месте — курорт Абастумани.

5. Заден-гора. Жители приносили здесь жертвы идолам; апостол сокрушил их и пошёл дальше.

6. Ацкури. Главное чудо пути — воскрешение сына правительницы и крещение всего края (см. карточку «Ацкури»).

7. Дальше по Грузии. Апостол проповедовал в Тао и Кларджети, в Мегрелии, Сванети и Абазгии.

8. На север. Затем он ушёл к аланам и зихам, а оттуда — в Скифию.

Где-то точное место известно, где-то — только название из летописи. Мы честно отмечаем это на карте.' AND r.seo_title IS 'Путь по Грузии — Паломник по Грузии' AND r.seo_description IS 'От моря через горы — шаг за шагом' AND EXISTS (SELECT 1 FROM settings WHERE key='palomnik_unified' AND value='1') ON CONFLICT(element_id,lang) DO UPDATE SET title=CASE WHEN COALESCE(element_i18n.title,'')='' THEN excluded.title ELSE element_i18n.title END,subtitle=CASE WHEN COALESCE(element_i18n.subtitle,'')='' THEN excluded.subtitle ELSE element_i18n.subtitle END,body=CASE WHEN COALESCE(element_i18n.body,'')='' THEN excluded.body ELSE element_i18n.body END,seo_title=CASE WHEN COALESCE(element_i18n.seo_title,'')='' THEN excluded.seo_title ELSE element_i18n.seo_title END,seo_description=CASE WHEN COALESCE(element_i18n.seo_description,'')='' THEN excluded.seo_description ELSE element_i18n.seo_description END;

INSERT INTO element_i18n(element_id,lang,title,subtitle,body,seo_title,seo_description) SELECT r.element_id,'en','Atskuri','The principal holy place of the apostolic journey','Atskuri is the principal place on the apostolic journey in Georgia. In antiquity, the town of Sosangeti stood here, with a large pagan temple.

According to tradition, the only son of a noble widow who ruled the region died. The Apostle Andrew raised him from the dead, and the ruler and all the people of Samtskhe were baptised. The priests stirred up the people against the new faith. The Apostle then proposed leaving the icon overnight in the temple of Apollo and Artemis. In the morning the statues of the gods lay shattered, while the icon remained unharmed.

At the inhabitants’ request, the Apostle left a copy of the image Not Made by Hands here. It became known as the Atskuri Icon of the Mother of God. The Byzantine emperor Heraclius venerated it in the 7th century. It survived beneath the cathedral’s collapsed dome during the earthquake of 1283 and, according to tradition, a fire in 1486. Today the icon is kept in the State Museum of Fine Arts of Georgia in Tbilisi. Its feast day is 28 August (15 August, Old Style).

Atskuri is regarded as Georgia’s first apostolic episcopal see. The great Cathedral of the Dormition (10th–11th centuries) now lies in ruins; archaeological excavations have been conducted here since 1988.','Atskuri — Pilgrim in Georgia','The principal holy place of the apostolic journey' FROM element_i18n r WHERE r.lang='ru' AND r.title IS 'Ацкури' AND r.subtitle IS 'Главная святыня апостольского пути' AND r.body IS 'Ацкури — главное место апостольского пути в Грузии. В древности здесь стоял город Сосангети с большим языческим храмом.

По преданию, у знатной вдовы, правившей краем, умер единственный сын. Апостол Андрей воскресил его — и правительница вместе со всем народом Самцхе приняла крещение. Жрецы подняли людей против новой веры. Тогда апостол предложил оставить икону на ночь в храме Аполлона и Артемиды. Наутро статуи богов лежали разбитыми, а икона осталась невредимой.

По просьбе жителей апостол оставил здесь копию Нерукотворного образа. Её назвали Ацкурской иконой Богородицы. Ей поклонялся византийский император Ираклий (VII век); она уцелела при землетрясении 1283 года под рухнувшим куполом собора и, по преданию, в огне в 1486 году. Сегодня икона хранится в Государственном музее искусств Грузии в Тбилиси. Память Ацкурской иконы — 28 августа (15 августа по старому стилю).

Ацкури считают первой апостольской кафедрой Грузии. От большого собора Успения (X–XI века) сегодня остались руины, а с 1988 года здесь ведут археологические раскопки.' AND r.seo_title IS 'Ацкури — Паломник по Грузии' AND r.seo_description IS 'Главная святыня апостольского пути' AND EXISTS (SELECT 1 FROM settings WHERE key='palomnik_unified' AND value='1') ON CONFLICT(element_id,lang) DO UPDATE SET title=CASE WHEN COALESCE(element_i18n.title,'')='' THEN excluded.title ELSE element_i18n.title END,subtitle=CASE WHEN COALESCE(element_i18n.subtitle,'')='' THEN excluded.subtitle ELSE element_i18n.subtitle END,body=CASE WHEN COALESCE(element_i18n.body,'')='' THEN excluded.body ELSE element_i18n.body END,seo_title=CASE WHEN COALESCE(element_i18n.seo_title,'')='' THEN excluded.seo_title ELSE element_i18n.seo_title END,seo_description=CASE WHEN COALESCE(element_i18n.seo_description,'')='' THEN excluded.seo_description ELSE element_i18n.seo_description END;

INSERT INTO element_i18n(element_id,lang,title,subtitle,body,seo_title,seo_description) SELECT r.element_id,'en','Companions','The Apostle did not travel alone','According to tradition, the Apostle Andrew did not come to Georgia alone. The Apostles Simon the Zealot and Matthias preached alongside him.

The Apostle Simon the Zealot was one of the Twelve. Together with Andrew, he reached Abasgia on the Black Sea coast and remained there to preach when Andrew travelled north. According to tradition, Simon prayed in a cave above a river and suffered martyrdom around AD 55. A church was built over his burial place in the 9th–10th centuries, and in the late 19th century Russian monks founded the New Athos Monastery in his name. His feast day is 23 May (10 May, Old Style).

The Apostle Matthias was chosen by lot to replace Judas, restoring the number of the Apostles to twelve. According to Georgian tradition, he preached in southwestern Georgia and was buried in the ancient fortress of Gonio near Batumi. A symbolic tomb is shown there today, on the site of the Roman praetorium. His feast day is 22 August (9 August, Old Style).','Companions — Pilgrim in Georgia','The Apostle did not travel alone' FROM element_i18n r WHERE r.lang='ru' AND r.title IS 'Спутники' AND r.subtitle IS 'Апостол шёл не один' AND r.body IS 'По преданию, апостол Андрей пришёл в Грузию не один. С ним проповедовали апостолы Симон Кананит и Матфий.

Апостол Симон Кананит — один из Двенадцати. Вместе с Андреем он дошёл до Абазгии на Черноморском побережье и остался там проповедовать, когда Андрей ушёл на север. По преданию, Симон молился в пещере над рекой, а около 55 года принял мученическую кончину. Над местом его погребения в IX–X веках поставили храм, а в конце XIX века русские монахи основали Ново-Афонский монастырь его имени. Память — 23 мая (10 мая по старому стилю).

Апостол Матфий был избран по жребию вместо Иуды, чтобы снова стало двенадцать апостолов. По грузинскому преданию, он проповедовал на юго-западе Грузии и похоронен в древней крепости Гонио у Батуми. Там, на месте римской претории, сегодня показывают его символическую гробницу. Память — 22 августа (9 августа по старому стилю).' AND r.seo_title IS 'Спутники — Паломник по Грузии' AND r.seo_description IS 'Апостол шёл не один' AND EXISTS (SELECT 1 FROM settings WHERE key='palomnik_unified' AND value='1') ON CONFLICT(element_id,lang) DO UPDATE SET title=CASE WHEN COALESCE(element_i18n.title,'')='' THEN excluded.title ELSE element_i18n.title END,subtitle=CASE WHEN COALESCE(element_i18n.subtitle,'')='' THEN excluded.subtitle ELSE element_i18n.subtitle END,body=CASE WHEN COALESCE(element_i18n.body,'')='' THEN excluded.body ELSE element_i18n.body END,seo_title=CASE WHEN COALESCE(element_i18n.seo_title,'')='' THEN excluded.seo_title ELSE element_i18n.seo_title END,seo_description=CASE WHEN COALESCE(element_i18n.seo_description,'')='' THEN excluded.seo_description ELSE element_i18n.seo_description END;

INSERT INTO element_i18n(element_id,lang,title) SELECT r.element_id,'en','The Apostle’s journey through Georgia' FROM element_i18n r WHERE r.lang='ru' AND r.title IS 'Путь апостола по Грузии' AND EXISTS (SELECT 1 FROM settings WHERE key='palomnik_unified' AND value='1') ON CONFLICT(element_id,lang) DO UPDATE SET title=CASE WHEN COALESCE(element_i18n.title,'')='' THEN excluded.title ELSE element_i18n.title END;

INSERT INTO element_i18n(element_id,lang,title,body) SELECT r.element_id,'en','For the pilgrim','The Apostle’s route can be travelled by car in three days, from the sea across the mountains to Tbilisi.

Day 1. Batumi — Gonio — Khulo. In the morning, visit Gonio Fortress and the tomb of the Apostle Matthias. Then head into mountainous Adjara, towards Khulo and Didachara.

Day 2. Goderdzi Pass — Abastumani — Akhaltsikhe. Cross the mountains into Samtskhe, following the Apostle’s journey. In Abastumani, visit the church decorated by Mikhail Nesterov. Stay overnight in Akhaltsikhe.

Day 3. Atskuri — Borjomi — Tbilisi. Visit the ruins of Atskuri Cathedral and the fortress above the Kura. In Tbilisi, see the Lurji Monastery, Georgia’s principal church dedicated to the Apostle Andrew, and the Museum of Fine Arts, where the Atskuri Icon is kept.

Feast days: 12 May — the arrival of the Apostle Andrew in Georgia and the dedication to the Mother of God, with the main service at the Lurji Monastery; 23 May — the Apostle Simon the Zealot; 22 August — the Apostle Matthias; 28 August — the Atskuri Icon of the Mother of God; 13 December — the Apostle Andrew the First-Called.

New Athos is not included in this itinerary: entry into Abkhazia is subject to legal restrictions under Georgian law.' FROM element_i18n r WHERE r.lang='ru' AND r.title IS 'Паломнику' AND r.body IS 'Путь апостола можно пройти за три дня на машине — от моря через горы к Тбилиси.

День 1. Батуми — Гонио — Хуло. Утром — крепость Гонио и гробница апостола Матфия. Затем дорога вглубь горной Аджарии, к Хуло и Дидачаре.

День 2. Перевал Годердзи — Абастумани — Ахалцихе. Через горы в Самцхе, как шёл апостол. В Абастумани — храм, расписанный Михаилом Нестеровым. Ночлег в Ахалцихе.

День 3. Ацкури — Боржоми — Тбилиси. Руины Ацкурского собора и крепость над Курой. В Тбилиси — Лурджи монастырь, главный храм апостола Андрея в Грузии, и Музей искусств, где хранится Ацкурская икона.

Дни памяти: 12 мая — приход апостола Андрея в Грузию и Удел Богоматери, главная служба — в Лурджи монастыре; 23 мая — апостол Симон Кананит; 22 августа — апостол Матфий; 28 августа — Ацкурская икона Богородицы; 13 декабря — апостол Андрей Первозванный.

Новый Афон в маршрут не включён: въезд в Абхазию имеет правовые ограничения со стороны Грузии.' AND EXISTS (SELECT 1 FROM settings WHERE key='palomnik_unified' AND value='1') ON CONFLICT(element_id,lang) DO UPDATE SET title=CASE WHEN COALESCE(element_i18n.title,'')='' THEN excluded.title ELSE element_i18n.title END,body=CASE WHEN COALESCE(element_i18n.body,'')='' THEN excluded.body ELSE element_i18n.body END;

INSERT INTO element_i18n(element_id,lang,title,subtitle,body,seo_title,seo_description) SELECT r.element_id,'en','Saint Nino, Equal to the Apostles, and her companions','4th century. The baptism of Georgia','Saint Nino is the enlightener of Georgia. In the 4th century her preaching led to the conversion of King Mirian and Queen Nana and the adoption of Christianity in Kartli. The Church honours her as Equal to the Apostles.

According to tradition, Nino came from Cappadocia through Jerusalem and Armenia, carrying a grapevine cross. Her journey in Georgia is associated with Lake Paravani, the ancient capital of Mtskheta and Bodbe in Kakheti.

This section tells the story of her journey, the sacred cross, her first disciples and the places where her memory lives on.','Saint Nino, Equal to the Apostles, and her companions — Pilgrim in Georgia','Saint Nino is the enlightener of Georgia. In the 4th century her preaching led to the conversion of King Mirian and Queen Nana and the adoption of Christianity' FROM element_i18n r WHERE r.lang='ru' AND r.title IS 'Равноапостольная Нина и её спутницы' AND r.subtitle IS 'IV век. Крещение Грузии' AND r.body IS 'Святая Нина — просветительница Грузии. В IV веке её проповедь привела к обращению царя Мириана и царицы Наны и принятию христианства в Картли. Церковь прославляет её как равноапостольную.

По преданию, Нина пришла из Каппадокии через Иерусалим и Армению, неся крест из виноградной лозы. Её путь в Грузии связывают с озером Паравани, древней столицей Мцхетой и Бодбе в Кахети.

В этом разделе — история её пути, святыня креста, первые ученицы и места, где память о Нине живёт до сих пор.' AND r.seo_title IS 'Равноапостольная Нина и её спутницы — Паломник' AND r.seo_description IS 'Святая Нина — просветительница Грузии. В IV веке её проповедь привела к обращению царя Мириана и царицы Наны и принятию христианства в Картли. Церковь прос' AND EXISTS (SELECT 1 FROM settings WHERE key='palomnik_unified' AND value='1') ON CONFLICT(element_id,lang) DO UPDATE SET title=CASE WHEN COALESCE(element_i18n.title,'')='' THEN excluded.title ELSE element_i18n.title END,subtitle=CASE WHEN COALESCE(element_i18n.subtitle,'')='' THEN excluded.subtitle ELSE element_i18n.subtitle END,body=CASE WHEN COALESCE(element_i18n.body,'')='' THEN excluded.body ELSE element_i18n.body END,seo_title=CASE WHEN COALESCE(element_i18n.seo_title,'')='' THEN excluded.seo_title ELSE element_i18n.seo_title END,seo_description=CASE WHEN COALESCE(element_i18n.seo_description,'')='' THEN excluded.seo_description ELSE element_i18n.seo_description END;

